 X("tbl-p178-0445", [[C("Potassium level (mEq/L)"), C("Quantity of KCl (1 mEq IV = 1 mmol IV; 8 mEq = 600 mg tablet)"), C("When to do the next control (sooner if the patient has vomiting or diarrhoea)")]],
   [r("4.0 or more", "None", "Monthly"), r("3.7 – 4.0", "None", "Monthly"), r("3.4 – 3.6", "20 - 40 mEq (1500-3000 mg)", "Monthly"), r("3.0 – 3.3", "60 mEq (4500 mg)", "Two weeks"),
    r("2.7 – 2.9", "80 mEq (6000 mg)", "One week"), r("2.4 – 2.6", "60 mmol IV and 6000 mg orally every 6 hours for 24 hours", "—"),
    r("2.0 – 2.3", "60 mmol IV and 7500 mg orally", "Every 6 hours with aggressive IV replacement. Consider holding the injectable until >2.4")],
   footnotes=["Source: Guidelines for Programmatic Management of Drug-resistant Tuberculosis, Emergency update 2008, WHO/HTM/TB/2008.402."],
   table_note="Every Slow-K 600 mg tablet contains 8 mEq of K; every magnesium tablet contains 150 mg magnesium oxide. Potassium IV supplementation should NOT exceed 20 mmol/hr of KCl (usual 40 mmol in 1 L NaCl 0.9%, maximum 60 mmol/L). Magnesium IV: maximum 5 g MgSO4 in 1 L NaCl 0.9% or dextrose 5%, not faster than 150 mg/min; if not an emergency 2 g in 100 ml over 1-2 hours or 4 g in 250 ml over 2-4 hours. Amiloride or spironolactone are useful in resistant cases.",
   flags=["K+ 2.4-2.6: '60 mmol IV and 6000 mg orally every 6 hours for 24 hours' would be 320 mEq oral plus IV per day if read literally; the 'every 6 hours' appears to belong to the monitoring column (as in the next row). The 'when to do the next control' cell is blank for this row."]),
 X("tbl-p194-0493", [[C("Client category"), C("Recommended ART regimen"), C("Comments")]],
   [r("Clients already on TB treatment presenting for ART initiation", "TDF (300 mg)/3TC (300 mg) once daily + DTG (50 mg twice daily)", "- Start ART as soon as possible with increased DTG dosing of 50 mg twice daily<br/>- Return to standard DTG dosing 50 mg once daily two weeks after the completion of TB treatment"),
    r("Clients developing TB while on a DTG-based ART regimen", "Increase DTG dose to 50 mg twice daily", "Clients must return to DTG 50 mg once daily 2 weeks after completing TB treatment."),
    r("Developing DS-TB while on an EFV-based ART regimen", "TDF/3TC+EFV 400 mg (once daily)", "- Check VL at the end of treatment. If VL is undetectable, the client can be transitioned to a once-daily FDC of TDF+3TC+DTG two weeks after completion of TB treatment<br/>- If VL is detectable, immediately switch to second line and continue adherence support (refer to the ART section)"),
    [C("Developing DS-TB while on a protease inhibitor (PI)-based ART regimen"), C("Consult an experienced HIV clinician or snapthirdline@mohcoag.org before choosing these options:<br/>TB patient on LPV/r:<br/>- Super-boost LPV/r to 400 mg/400 mg by adding 300 mg ritonavir, and continue until 2 weeks after completion of TB treatment<br/>- Double-dose LPV/r to 800 mg/200 mg twice daily (double dosing is only for clients >10 years of age) and continue until 2 weeks after completion of TB treatment<br/>- If evidence of VL suppression in the past 3-6 months, switch to a DTG-based second-line regimen and continue twice-daily DTG until 2 weeks after completion of TB treatment<br/>TB patient on ATV/r or DRV/r:<br/>- Do not combine with rifampicin<br/>- Change to DTG twice daily if DTG-naive, or LPV/r with adjustments as above if DTG-experienced<br/>Patients who may be failing ART:<br/>- Follow guidance on managing treatment failure", cs=2)],
    {"section": "For clients with multidrug-resistant TB"},
    [C("EFV and bedaquiline (BDQ)"), C("- EFV should not be used with BDQ.<br/>- EFV induces CYP3A activity and co-administration with BDQ may result in reduced BDQ exposure and loss of BDQ activity.<br/>- DTG is the preferred INSTI for clients receiving BDQ.", cs=2)],
    [C("Delamanid (DLM) and ARVs"), C("- DLM is generally considered safe to administer with ART.<br/>- Evidence shows safety with EFV, TDF and LPV/r.<br/>- No LPV/r dose adjustment is needed for TB patients on DLM. No long-term studies have been done on drug-drug interactions between DLM and ARVs. DTG is the preferred INSTI for clients receiving DLM.", cs=2)]],
   table_note="For all clients, maintain the same NRTI backbone provided no dose adjustment is necessary and the client is virally suppressed.", pages=[194, 195]),
 X("tbl-p201-0516", [[C("Weight"), C("Current ART regimen"), C("Initial regimen / suggested modification (NRTIs based on HIV guidelines)")]],
   [{"section": "Treatment of HIV-associated TB in children – patients initiating ART while on TB treatment"},
    [C("< 10 kg"), C("Not on ART"), C("LPV/r with 1:1 ritonavir boosting ¹ ⁶ (recommended) or ABC-3TC-AZT ² ³ (recommended if ritonavir is not available) or NVP ² ³ ⁴ ⁵")],
    [C("10-20 kg"), C("Not on ART"), C("EFV (recommended) or LPV/r with 1:1 ritonavir boosting ¹ ⁶ or ABC-3TC-AZT ² ³")],
    [C("> 20 kg"), C("Not on ART"), C("DTG ⁷ twice daily (recommended)")],
    {"section": "Modifications to ART when initiating TB treatment in patients on ART"},
    [C("< 10 kg", rs=2), C("NVP"), C("Continue NVP ² ³ ⁴ ⁵")],
    r("LPV/r", "LPV/r with 1:1 ritonavir boosting ¹ ⁶ (recommended) or ABC-3TC-AZT ² ³ (recommended if ritonavir not available) or NVP ² ³ ⁴ ⁵"),
    [C("10-20 kg", rs=3), C("NVP or EFV"), C("EFV ⁸")],
    r("LPV/r (1st-line ART)", "LPV/r with 1:1 ritonavir boosting ¹ ⁶ (recommended) or EFV (recommended if VL undetectable in the last 6 months) or ABC-3TC-AZT ² ³"),
    r("LPV/r (2nd-line treatment)", "LPV/r with 1:1 ritonavir boosting ⁶ (recommended) or ABC-3TC-AZT ² ³"),
    [C("> 20 kg", rs=3), C("NVP or EFV"), C("EFV ⁸ ⁹")],
    r("ATV/r or LPV/r (1st or 2nd line)", "LPV/r double dose ⁶ or DTG ⁷ twice daily (if VL confirmed undetectable at TB treatment initiation)"),
    r("DTG", "Twice-daily DTG ⁷")],
   footnotes=["1. See Dosing Table **** for 1:1 LPV/r (ritonavir solution and capsules) [as printed]. 2. NEVER continue ABC-3TC-AZT or an NVP-based regimen for more than 2 weeks after rifampicin is discontinued. 3. Consider ABC-3TC-AZT or NVP if intolerant to LPV/r. 4. Avoid NVP if prior exposure to PMTCT or ART. 5. Start at full dose and increase the dose to 200 mg/m²/dose if formulation allows when co-administered with rifampicin. 6. LPV/r can be administered as a double dose instead of 1:1 in children swallowing LPV/r tablets, reduced to standard dosing 2 weeks after rifampicin is discontinued. 7. DTG must be given twice daily while on TB treatment and continued twice daily for two weeks after rifampicin is discontinued. 8. NVP can be continued during TB treatment instead of EFV if intolerance or cannot swallow EFV. 9. Plan to change to DTG from EFV following completion of TB treatment (two weeks after rifampicin is stopped) if viral load is undetectable."],
   table_note="Guiding principles: always immediately check viral load and CD4 in a patient on ART who is diagnosed with TB; if VL is detectable avoid a one-drug change and manage as treatment failure considering ART/ATT interactions; consider ART and PMTCT history; NRTI companion drugs per HIV guidelines (weight, comorbidities, prior NRTI exposure); consult TB/HIV experts (NTCP, ENAP, partners) for questions and patients failing second-line ART or a PI.",
   pages=[201, 202],
   flags=["Footnote 1 refers to 'Dosing Table ****' (unfinished cross-reference); footnote 5 runs into footnote 6 in the PDF.", "The table predates paediatric DTG for children <20 kg: current WHO guidance prefers DTG (twice daily with rifampicin) for children ≥4 weeks and ≥3 kg; the table still recommends LPV/r, NVP or EFV for <20 kg."]),
